/**
 * @file src/lib/useFacadeSubscription.ts
 * Subscribe to facade events with automatic cleanup (Svelte 5 runes).
 */

import { onDestroy } from 'svelte';
import { facade } from '../bus/gameFacade.js';
import type { GameEvent, GameEventType } from '../bus/events.js';

type Handler = (event: GameEvent) => void;

/**
 * Register facade listener(s) for the component lifetime.
 * Call from component script setup (not inside $effect).
 */
export function useFacadeSubscription(
  eventTypes: GameEventType | GameEventType[],
  handler: Handler,
): void {
  const types = Array.isArray(eventTypes) ? eventTypes : [eventTypes];
  const unsubs = types.map((t) => facade.subscribe(t, handler));
  onDestroy(() => {
    for (const u of unsubs) u();
  });
}
